import torch
def layer_norm(x, gamma, beta, eps=1e-5):
    mean = x.mean(dim=-1, keepdim=True)
    var = (x-mean).square().mean(dim=-1, keepdim=True)
    return (x-mean) * torch.rsqrt(var+eps) * gamma + beta

import torch
def batch_norm(x, gamma, beta, running_mean, running_var, training, momentum=.1, eps=1e-5):
    if training:
        n = x.shape[0]
        if n <= 1: raise ValueError("training requires N > 1")
        mean = x.mean(0)
        var = (x-mean).square().mean(0)
        with torch.no_grad():
            running_mean.lerp_(mean, momentum)
            running_var.lerp_(var*n/(n-1), momentum)
    else:
        mean, var = running_mean, running_var
    return (x-mean)*torch.rsqrt(var+eps)*gamma+beta

import torch
def dropout(x, p=.5, training=True):
    if not 0 <= p <= 1: raise ValueError("p must be in [0,1]")
    if not training or p == 0: return x
    if p == 1: return torch.zeros_like(x)
    mask = torch.rand_like(x) >= p
    return x * mask.to(x.dtype) / (1-p)

import torch
def sample_topk(logits, k, temperature=1.0):
    assert logits.ndim == 1 and 1 <= k <= logits.numel() and temperature > 0
    values, ids = torch.topk(logits.float()/temperature, k)
    local = torch.multinomial(torch.softmax(values, -1), 1)
    return ids[local].item()

def beam_search(next_logprobs, start, eos, width=4, max_steps=32):
    assert width > 0
    beams = [(list(start), 0.0, False)]
    for _ in range(max_steps):
        candidates = []
        for seq, score, done in beams:
            if done:
                candidates.append((seq, score, True))
                continue
            lp = next_logprobs(seq)
            for token in sorted(range(len(lp)), key=lambda i: lp[i], reverse=True)[:width]:
                candidates.append((seq+[token], score+float(lp[token]), token == eos))
        beams = sorted(candidates, key=lambda b: b[1], reverse=True)[:width]
        if all(b[2] for b in beams): break
    return beams[0][0]

import torch
def run_epoch(model, loader, loss_fn, device, optimizer=None):
    training = optimizer is not None
    model.train(training)
    total, count = 0.0, 0
    with torch.set_grad_enabled(training):
        for x, y in loader:
            x, y = x.to(device), y.to(device)
            if training: optimizer.zero_grad(set_to_none=True)
            loss = loss_fn(model(x), y)  # reduction='mean'
            if training:
                loss.backward()
                optimizer.step()
            total += loss.item() * len(x)
            count += len(x)
    return total / count if count else float("nan")

def accumulated_step(model, batches, loss_fn, optimizer):
    total = sum(len(y) for x, y in batches)
    if total == 0: raise ValueError("empty effective batch")
    optimizer.zero_grad(set_to_none=True)
    for x, y in batches:
        loss = loss_fn(model(x), y)  # reduction='mean'
        (loss * (len(y) / total)).backward()
    optimizer.step()

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target-x in seen:
            return seen[target-x], i
        seen[x] = i
    return None

from collections import deque
def shortest_path(graph, start, goal):
    queue, parent = deque([start]), {start: None}
    while queue:
        u = queue.popleft()
        if u == goal:
            path = []
            while u is not None:
                path.append(u)
                u = parent[u]
            return path[::-1]
        for v in graph.get(u, []):
            if v not in parent:
                parent[v] = u
                queue.append(v)
    return None

import heapq
def top_k(stream, k):
    if k < 0: raise ValueError("k must be nonnegative")
    if k == 0: return []
    heap = []
    for x in stream:
        if len(heap) < k: heapq.heappush(heap, x)
        elif x > heap[0]: heapq.heapreplace(heap, x)
    return sorted(heap, reverse=True)

def coin_change(coins, amount):
    if amount < 0 or any(c <= 0 for c in coins):
        raise ValueError("positive coins and nonnegative amount required")
    dp = [0] + [float("inf")] * amount
    for a in range(1, amount+1):
        for c in coins:
            if c <= a: dp[a] = min(dp[a], dp[a-c]+1)
    return -1 if dp[amount] == float("inf") else dp[amount]

def has_cycle(head):
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow, fast = slow.next, fast.next.next
        if slow is fast: return True
    return False

