import numpy as np
def ctc_log_probability(log_probs, labels, blank=0):
    # Small reference implementation; log_probs has shape [time, classes].
    lp = np.asarray(log_probs, dtype=float)
    labels = list(labels)
    if lp.ndim != 2 or blank in labels:
        raise ValueError("invalid emissions or blank in target")
    T, classes = lp.shape
    if not 0 <= blank < classes or any(y < 0 or y >= classes for y in labels):
        raise ValueError("invalid label index")
    if T == 0:
        return 0.0 if not labels else -np.inf
    z = [blank]
    for y in labels:
        z.extend([y, blank])
    prev = np.full(len(z), -np.inf)
    prev[0] = lp[0, blank]
    if labels:
        prev[1] = lp[0, z[1]]
    for t in range(1, T):
        cur = np.full(len(z), -np.inf)
        for s, label in enumerate(z):
            incoming = [prev[s]]
            if s >= 1:
                incoming.append(prev[s-1])
            if s >= 2 and label != blank and label != z[s-2]:
                incoming.append(prev[s-2])
            cur[s] = np.logaddexp.reduce(incoming) + lp[t, label]
        prev = cur
    return prev[0] if not labels else np.logaddexp(prev[-1], prev[-2])
