def knapsack(items, capacity):
    # Positive integer weights; selecting nothing is allowed.
    if capacity < 0 or any(w <= 0 for w, _ in items):
        raise ValueError('invalid capacity or weight')
    best = [0] * (capacity + 1)
    for weight, value in items:
        for c in range(capacity, weight - 1, -1):
            best[c] = max(best[c], best[c - weight] + value)
    return best[capacity]

