def reduce_scatter_then_gather(rank_vectors):
    # Single-process semantic reference, not a network implementation.
    p = len(rank_vectors)
    if p == 0: raise ValueError('no ranks')
    n = len(rank_vectors[0])
    if n % p or any(len(v) != n for v in rank_vectors):
        raise ValueError('equal vectors divisible into equal shards required')
    width = n//p
    shards = [[sum(v[j] for v in rank_vectors)
               for j in range(r*width,(r+1)*width)] for r in range(p)]
    gathered = [x for shard in shards for x in shard]
    return shards, [gathered[:] for _ in range(p)]

def weighted_gradient(means, counts):
    if len(means) != len(counts) or not means or sum(counts) <= 0:
        raise ValueError('invalid inputs')
    if any(n < 0 for n in counts): raise ValueError('negative count')
    if any(len(g) != len(means[0]) for g in means): raise ValueError('shape mismatch')
    return [sum(n*g[j] for g,n in zip(means,counts))/sum(counts)
            for j in range(len(means[0]))]

